95: // Start an actor run and return { runId, datasetId }
96: async function startActor(token, actorId, inputJson) {
97:     // Convert "author/actor" format to "author~actor" for API compatibility
98:     const apiActorId = actorId.replace('/', '~');
99:     const url = `https://api.apify.com/v2/acts/${apiActorId}/runs?token=${encodeURIComponent(token)}`;
100: 
101:     let data;
102:     try {
103:         data = JSON.parse(inputJson);
104:     } catch (e) {
105:         console.error(`Error: Invalid JSON input: ${e.message}`);
106:         process.exit(1);
107:     }
108: 
109:     const response = await fetch(url, {
110:         method: 'POST',
111:         headers: {
112:             'Content-Type': 'application/json',
113:             'User-Agent': `${USER_AGENT}/start_actor`,
114:         },
115:         body: JSON.stringify(data),
116:     });
117: 
118:     if (response.status === 404) {
119:         console.error(`Error: Actor '${actorId}' not found`);
120:         process.exit(1);
121:     }
122: 
123:     if (!response.ok) {
124:         const text = await response.text();
125:         console.error(`Error: API request failed (${response.status}): ${text}`);
126:         process.exit(1);
127:     }
128: 
129:     const result = await response.json();
130:     return {
131:         runId: result.data.id,
132:         datasetId: result.data.defaultDatasetId,
133:     };
134: }
