136: // Poll run status until complete or timeout
137: async function pollUntilComplete(token, runId, timeout, interval) {
138:     const url = `https://api.apify.com/v2/actor-runs/${runId}?token=${encodeURIComponent(token)}`;
139:     const startTime = Date.now();
140:     let lastStatus = null;
141: 
142:     while (true) {
143:         const response = await fetch(url);
144:         if (!response.ok) {
145:             const text = await response.text();
146:             console.error(`Error: Failed to get run status: ${text}`);
147:             process.exit(1);
148:         }
149: 
150:         const result = await response.json();
151:         const status = result.data.status;
152: 
153:         // Only print when status changes
154:         if (status !== lastStatus) {
155:             console.log(`Status: ${status}`);
156:             lastStatus = status;
157:         }
158: 
159:         if (['SUCCEEDED', 'FAILED', 'ABORTED', 'TIMED-OUT'].includes(status)) {
160:             return status;
161:         }
162: 
163:         const elapsed = (Date.now() - startTime) / 1000;
164:         if (elapsed > timeout) {
165:             console.error(`Warning: Timeout after ${timeout}s, actor still running`);
166:             return 'TIMED-OUT';
167:         }
168: 
169:         await sleep(interval * 1000);
170:     }
171: }
