217:                     }
218:                     return strValue;
219:                 });
220:                 csvLines.push(values.join(','));
221:             }
222: 
223:             writeFileSync(outputPath, csvLines.join('\n'));
224:         } else {
225:             writeFileSync(outputPath, '');
226:         }
227:     }
